export async function loadAccount(accountId, accountStore, audit) {
  if (typeof accountId !== 'string' || accountId.length === 0) {
    throw new TypeError('accountId must be a non-empty string');
  }

  const account = await accountStore.findById(accountId);
  if (account === null) return null;

  await audit.record('account_loaded', { accountId });
  return account;
}

