import { describe, expect, it, vi } from 'vitest';
import { loadAccount } from '../../src/services/loadAccount.js';

describe('loadAccount', () => {
  it('returns the stored account and records a successful lookup', async () => {
    const account = { id: 'acct-42', tier: 'standard' };
    const accountStore = { findById: vi.fn().mockResolvedValue(account) };
    const audit = { record: vi.fn().mockResolvedValue(undefined) };

    await expect(loadAccount('acct-42', accountStore, audit)).resolves.toBe(account);
    expect(accountStore.findById).toHaveBeenCalledWith('acct-42');
    expect(audit.record).toHaveBeenCalledWith('account_loaded', { accountId: 'acct-42' });
  });

  it('returns null and does not record an audit event when the account is absent', async () => {
    const accountStore = { findById: vi.fn().mockResolvedValue(null) };
    const audit = { record: vi.fn().mockResolvedValue(undefined) };

    await expect(loadAccount('missing', accountStore, audit)).resolves.toBeNull();
    expect(audit.record).not.toHaveBeenCalled();
  });

  it('rejects an empty account ID before accessing dependencies', async () => {
    const accountStore = { findById: vi.fn() };
    const audit = { record: vi.fn() };

    await expect(loadAccount('', accountStore, audit)).rejects.toThrow(TypeError);
    expect(accountStore.findById).not.toHaveBeenCalled();
    expect(audit.record).not.toHaveBeenCalled();
  });
});

