export function retryDelays(maxRetries, baseDelayMs, capMs) {
  if (
    !Number.isInteger(maxRetries) || maxRetries < 0 ||
    !Number.isInteger(baseDelayMs) || baseDelayMs < 0 ||
    !Number.isInteger(capMs) || capMs < 0
  ) {
    throw new RangeError('retry parameters must be non-negative integers');
  }

  return Array.from({ length: maxRetries }, (_, index) =>
    Math.min(baseDelayMs * 2 ** index, capMs)
  );
}

