import { describe, it } from 'mocha';
import assert from 'node:assert/strict';
import { retryDelays } from '../src/retry/retryDelays.js';

describe('retryDelays', () => {
  it('returns capped exponential delays for each retry', () => {
    assert.deepEqual(retryDelays(5, 100, 450), [100, 200, 400, 450, 450]);
  });

  it('returns an empty list when no retries are requested', () => {
    assert.deepEqual(retryDelays(0, 100, 1000), []);
  });

  it('returns zero delays when the base delay is zero', () => {
    assert.deepEqual(retryDelays(3, 0, 500), [0, 0, 0]);
  });

  it('rejects negative or fractional parameters', () => {
    assert.throws(() => retryDelays(-1, 100, 500), RangeError);
    assert.throws(() => retryDelays(2, 1.5, 500), RangeError);
  });
});

