  it('uses the default fallback for invalid and non-positive values', () => {
    assert.equal(parsePageSize('not-a-number'), 25);
    assert.equal(parsePageSize('0'), 25);
    assert.equal(parsePageSize('-3'), 25);
  });

  it('uses a supplied fallback for invalid input', () => {
    assert.equal(parsePageSize('2.5', 12), 12);
  });

  it('returns valid integer sizes and caps them at 100', () => {
    assert.equal(parsePageSize('40'), 40);
    assert.equal(parsePageSize('250'), 100);
  });
